INSERT INTO exercicio (id, nome, imagem, musculo_principal, musculo_secundario, descricao, tutorial, exemplos) VALUES
('a1b2c3d4-e5f6-7890-1234-567890abcdef', 'Supino reto (barra)', '', ARRAY['Peitoral maior'], ARRAY['Deltoide anterior', 'Tríceps'], 'Exercício fundamental para o desenvolvimento do peitoral, realizado em um banco plano com uma barra.', ARRAY['Deite-se no banco com os pés firmes no chão.', 'Segure a barra com as mãos um pouco além da largura dos ombros.', 'Abaixe a barra controladamente até tocar o meio do peito.', 'Empurre a barra de volta à posição inicial, estendendo os cotovelos.'], ARRAY[]::varchar[]),
('b2c3d4e5-f6a7-8901-2345-67890abcdef1', 'Supino inclinado (halter)', '', ARRAY['Peitoral superior'], ARRAY['Deltoide anterior', 'Tríceps'], 'Variação do supino focada na porção superior do peitoral, utilizando halteres para maior amplitude.', ARRAY['Ajuste o banco para um ângulo de 30 a 45 graus.', 'Deite-se segurando um halter em cada mão na altura dos ombros.', 'Empurre os halteres para cima até que os braços estejam estendidos.', 'Abaixe os halteres de forma controlada até a posição inicial.'], ARRAY[]::varchar[]),
('c3d4e5f6-a7b8-9012-3456-7890abcdef12', 'Supino em máquina', '', ARRAY['Peitoral maior'], ARRAY['Deltoide anterior', 'Tríceps'], 'Exercício guiado para o peitoral que oferece maior estabilidade e segurança.', ARRAY['Ajuste o banco para que as manoplas fiquem na altura do meio do peito.', 'Sente-se com as costas totalmente apoiadas e segure as manoplas.', 'Empurre para frente até a extensão completa dos braços.', 'Retorne à posição inicial de maneira controlada.'], ARRAY[]::varchar[]),
('d4e5f6a7-b8c9-0123-4567-890abcdef123', 'Puxada frente (aberta / neutra)', '', ARRAY['Grande dorsal (Latíssimo do dorso)'], ARRAY['Bíceps', 'Romboides', 'Trapézio'], 'Exercício essencial para a largura das costas, realizado em uma polia alta.', ARRAY['Sente-se na máquina e ajuste o apoio dos joelhos.', 'Segure a barra com uma pegada aberta (ou neutra).', 'Puxe a barra para baixo em direção à parte superior do peito, inclinando o tronco levemente para trás.', 'Retorne a barra à posição inicial de forma controlada.'], ARRAY[]::varchar[]),
('e5f6a7b8-c9d0-1234-5678-90abcdef1234', 'Puxada frente supinada', '', ARRAY['Grande dorsal (Latíssimo do dorso)'], ARRAY['Bíceps', 'Romboides'], 'Variação da puxada com pegada invertida (supinada), que aumenta a ativação do bíceps.', ARRAY['Sente-se na máquina e ajuste o apoio dos joelhos.', 'Segure a barra com as palmas das mãos voltadas para você (pegada supinada), na largura dos ombros.', 'Puxe a barra para baixo até a parte superior do peito.', 'Retorne lentamente à posição inicial.'], ARRAY[]::varchar[]),
('f6a7b8c9-d0e1-2345-6789-0abcdef12345', 'Barra fixa (assistida)', '', ARRAY['Grande dorsal (Latíssimo do dorso)'], ARRAY['Bíceps', 'Romboides', 'Trapézio'], 'Exercício de peso corporal para as costas, com assistência para iniciantes.', ARRAY['Ajuste o nível de assistência da máquina (graviton).', 'Suba na plataforma e segure a barra com a pegada desejada.', 'Puxe seu corpo para cima até que o queixo passe da barra.', 'Desça de forma controlada até a extensão completa dos braços.'], ARRAY[]::varchar[]),
('a7b8c9d0-e1f2-3456-7890-1bcdef123456', 'Remada curvada', '', ARRAY['Grande dorsal (Latíssimo do dorso)'], ARRAY['Romboides', 'Trapézio', 'Bíceps', 'Lombar'], 'Exercício com peso livre para espessura das costas, que exige boa estabilização do core.', ARRAY['Incline o tronco para frente, mantendo a coluna reta.', 'Segure a barra com uma pegada pronada (ou supinada).', 'Puxe a barra em direção ao abdômen, contraindo os músculos das costas.', 'Abaixe a barra de forma controlada.'], ARRAY[]::varchar[]),
('b8c9d0e1-f2a3-4567-8901-cdef12345678', 'Remada baixa', '', ARRAY['Grande dorsal (Latíssimo do dorso)'], ARRAY['Romboides', 'Trapézio', 'Bíceps'], 'Exercício sentado em máquina a cabo, focado na porção média das costas.', ARRAY['Sente-se na máquina com os pés apoiados e os joelhos levemente flexionados.', 'Segure o puxador com a coluna reta.', 'Puxe o puxador em direção ao abdômen, mantendo os cotovelos próximos ao corpo.', 'Retorne à posição inicial de forma controlada.'], ARRAY[]::varchar[]),
('c9d0e1f2-a3b4-5678-9012-def123456789', 'Remada alta no cross', '', ARRAY['Deltoide lateral', 'Trapézio'], ARRAY['Bíceps', 'Deltoide anterior'], 'Exercício para ombros e trapézio realizado com a polia baixa de um crossover.', ARRAY['Fique em pé de frente para a polia baixa, segurando a barra.', 'Puxe a barra para cima em direção ao queixo, elevando os cotovelos.', 'Mantenha os cotovelos mais altos que as mãos.', 'Abaixe a barra de forma controlada.'], ARRAY[]::varchar[]),
('d0e1f2a3-b4c5-6789-0123-ef1234567890', 'Agachamento no Smith', '', ARRAY['Quadríceps', 'Glúteos'], ARRAY['Isquiotibiais', 'Adutores'], 'Variação do agachamento em uma máquina guiada, que oferece mais estabilidade.', ARRAY['Posicione a barra do Smith sobre os ombros.', 'Coloque os pés um pouco à frente da linha do corpo.', 'Agache até que as coxas fiquem paralelas ao chão, mantendo a coluna reta.', 'Empurre de volta à posição inicial.'], ARRAY[]::varchar[]),
('e1f2a3b4-c5d6-7890-1234-f12345678901', 'Leg press', '', ARRAY['Quadríceps', 'Glúteos'], ARRAY['Isquiotibiais', 'Adutores'], 'Exercício de pressão com as pernas em máquina, excelente para volume e força nos membros inferiores.', ARRAY['Sente-se na máquina e posicione os pés na plataforma, na largura dos ombros.', 'Destrave a plataforma e flexione os joelhos, trazendo o peso em sua direção.', 'Empurre a plataforma de volta à posição inicial, sem travar os joelhos.', 'Mantenha a lombar e os glúteos sempre em contato com o banco.'], ARRAY[]::varchar[]),
('f2a3b4c5-d6e7-8901-2345-123456789012', 'Hack machine', '', ARRAY['Quadríceps'], ARRAY['Glúteos', 'Isquiotibiais', 'Adutores'], 'Máquina de agachamento que guia o movimento, focando intensamente no quadríceps.', ARRAY['Posicione-se na máquina com os ombros sob os apoios e as costas no encosto.', 'Coloque os pés na plataforma, na largura dos ombros.', 'Agache flexionando os joelhos, mantendo a coluna apoiada.', 'Empurre a plataforma para cima até a posição inicial.'], ARRAY[]::varchar[]),
('a3b4c5d6-e7f8-9012-3456-234567890123', 'Levantamento terra (tradicional)', '', ARRAY['Isquiotibiais', 'Glúteos', 'Lombar'], ARRAY['Quadríceps', 'Trapézio', 'Grande dorsal'], 'Exercício composto que trabalha quase todo o corpo, fundamental para força geral.', ARRAY['Posicione-se com os pés sob a barra, na largura do quadril.', 'Agache e segure a barra com as mãos por fora dos joelhos.', 'Levante a barra mantendo as costas retas, estendendo quadris e joelhos simultaneamente.', 'Abaixe a barra de forma controlada, revertendo o movimento.'], ARRAY[]::varchar[]),
('b4c5d6e7-f8a9-0123-4567-345678901234', 'Desenvolvimento (halter)', '', ARRAY['Deltoide anterior'], ARRAY['Deltoide lateral', 'Tríceps', 'Trapézio'], 'Exercício para ombros realizado com halteres, permitindo um movimento mais natural.', ARRAY['Sente-se em um banco com apoio para as costas, segurando um halter em cada mão na altura dos ombros.', 'Empurre os halteres para cima até a extensão quase completa dos braços.', 'Abaixe os halteres de forma controlada até a posição inicial.', 'Mantenha o abdômen contraído para estabilizar a coluna.'], ARRAY[]::varchar[]),
('c5d6e7f8-a9b0-1234-5678-456789012345', 'Desenvolvimento em máquina', '', ARRAY['Deltoide anterior'], ARRAY['Deltoide lateral', 'Tríceps'], 'Variação do desenvolvimento em máquina, que oferece um movimento guiado e seguro.', ARRAY['Ajuste o banco para que as manoplas fiquem na altura dos ombros.', 'Sente-se com as costas apoiadas e segure as manoplas.', 'Empurre para cima até a extensão dos braços.', 'Retorne à posição inicial de forma controlada.'], ARRAY[]::varchar[]),
('d6e7f8a9-b0c1-2345-6789-567890123456', 'Crucifixo máquina', '', ARRAY['Peitoral maior'], ARRAY['Deltoide anterior'], 'Exercício de isolamento para o peitoral, também conhecido como Peck Deck.', ARRAY['Sente-se na máquina com as costas apoiadas.', 'Posicione os antebraços nos apoios ou segure as manoplas.', 'Force os braços para se encontrarem na frente do corpo, contraindo o peitoral.', 'Retorne à posição inicial de forma controlada, alongando o peitoral.'], ARRAY[]::varchar[]),
('e7f8a9b0-c1d2-3456-7890-678901234567', 'Elevação lateral', '', ARRAY['Deltoide lateral'], ARRAY['Deltoide anterior', 'Trapézio'], 'Exercício de isolamento para a porção lateral dos ombros, criando uma aparência mais larga.', ARRAY['Fique em pé, segurando um halter em cada mão ao lado do corpo.', 'Eleve os braços para os lados até a altura dos ombros, com os cotovelos levemente flexionados.', 'Mantenha o core firme para evitar balanços.', 'Abaixe os halteres de forma controlada.'], ARRAY[]::varchar[]),
('f8a9b0c1-d2e3-4567-8901-789012345678', 'Elevação frontal', '', ARRAY['Deltoide anterior'], ARRAY['Peitoral superior', 'Deltoide lateral'], 'Exercício para a parte da frente dos ombros, geralmente feito com halteres ou barra.', ARRAY['Fique em pé, segurando halteres (ou uma barra) na frente das coxas.', 'Eleve os pesos para frente e para cima, até a altura dos ombros.', 'Mantenha os braços estendidos ou com uma leve flexão no cotovelo.', 'Abaixe os pesos de forma controlada.'], ARRAY[]::varchar[]),
('a9b0c1d2-e3f4-5678-9012-890123456789', 'Rosca direta (barra)', '', ARRAY['Bíceps braquial'], ARRAY['Braquial', 'Braquiorradial'], 'Exercício clássico para o desenvolvimento do bíceps, realizado com uma barra reta ou W.', ARRAY['Fique em pé, segurando a barra com as palmas das mãos para cima (pegada supinada).', 'Mantenha os cotovelos fixos ao lado do corpo.', 'Flexione os cotovelos, elevando a barra em direção aos ombros.', 'Abaixe a barra de forma controlada até a extensão completa dos braços.'], ARRAY[]::varchar[]),
('b0c1d2e3-f4a5-6789-0123-901234567890', 'Rosca alternada', '', ARRAY['Bíceps braquial'], ARRAY['Braquial', 'Braquiorradial'], 'Variação da rosca com halteres, trabalhando um braço de cada vez.', ARRAY['Fique em pé ou sentado, segurando um halter em cada mão com pegada supinada.', 'Flexione um cotovelo, elevando o halter em direção ao ombro.', 'Abaixe o halter de forma controlada.', 'Repita o movimento com o outro braço.'], ARRAY[]::varchar[]),
('c1d2e3f4-a5b6-7890-1234-012345678901', 'Rosca scott', '', ARRAY['Bíceps braquial'], ARRAY['Braquial'], 'Exercício de isolamento para o bíceps que utiliza um banco para apoiar os braços, minimizando o balanço.', ARRAY['Sente-se no banco Scott e ajuste a altura para que as axilas fiquem apoiadas.', 'Segure a barra ou halteres com pegada supinada.', 'Flexione os cotovelos, trazendo o peso para cima até a contração máxima do bíceps.', 'Estenda os cotovelos de forma controlada, retornando à posição inicial.'], ARRAY[]::varchar[]),
('d2e3f4a5-b6c7-8901-2345-123456789012', 'Tríceps testa', '', ARRAY['Tríceps braquial'], ARRAY[]::varchar[], 'Exercício deitado para tríceps, focado em todas as cabeças do músculo.', ARRAY['Deite-se em um banco plano, segurando uma barra (ou halteres) acima do peito.', 'Flexione os cotovelos, abaixando o peso em direção à testa.', 'Mantenha os braços (úmeros) imóveis e perpendiculares ao chão.', 'Empurre o peso de volta à posição inicial, estendendo os cotovelos.'], ARRAY[]::varchar[]),
('e3f4a5b6-c7d8-9012-3456-234567890123', 'Tríceps barra no cross', '', ARRAY['Tríceps braquial'], ARRAY[]::varchar[], 'Exercício de isolamento para tríceps na polia alta, ótimo para a cabeça lateral do músculo.', ARRAY['Fique em pé de frente para a polia alta, segurando a barra com pegada pronada.', 'Mantenha os cotovelos fixos ao lado do corpo.', 'Empurre a barra para baixo até a extensão completa dos braços.', 'Retorne à posição inicial de forma controlada.'], ARRAY[]::varchar[]),
('f4a5b6c7-d8e9-0123-4567-345678901234', 'Tríceps maquina', '', ARRAY['Tríceps braquial'], ARRAY[]::varchar[], 'Exercício guiado para tríceps, que permite focar na contração do músculo com estabilidade.', ARRAY['Sente-se na máquina e ajuste o banco.', 'Segure as manoplas com as palmas para baixo ou em posição neutra.', 'Empurre para baixo até que os braços estejam totalmente estendidos.', 'Retorne lentamente à posição inicial.'], ARRAY[]::varchar[]),
('a5b6c7d8-e9f0-1234-5678-456789012345', 'Legpress horizontal', '', ARRAY['Quadríceps'], ARRAY['Glúteos', 'Isquiotibiais'], 'Variação do leg press realizada em uma máquina horizontal, com foco em quadríceps e glúteos.', ARRAY['Sente-se na máquina com as costas totalmente apoiadas.', 'Posicione os pés na plataforma, na largura dos ombros.', 'Empurre a plataforma para frente até estender as pernas, sem travar os joelhos.', 'Retorne de forma controlada, flexionando os joelhos.'], ARRAY[]::varchar[]),
('b6c7d8e9-f0a1-2345-6789-567890123456', 'Cadeira extensora', '', ARRAY['Quadríceps'], ARRAY[]::varchar[], 'Exercício de isolamento para o quadríceps, que promove definição na parte frontal da coxa.', ARRAY['Sente-se na máquina e ajuste o apoio para que fique sobre a parte inferior das canelas.', 'Segure os apoios laterais para estabilidade.', 'Estenda os joelhos, elevando o peso até a extensão completa.', 'Abaixe o peso de forma controlada.'], ARRAY[]::varchar[]),
('c7d8e9f0-a1b2-3456-7890-678901234567', 'Cadeira flexora', '', ARRAY['Isquiotibiais'], ARRAY['Panturrilha'], 'Exercício de isolamento para os músculos posteriores da coxa, realizado sentado.', ARRAY['Sente-se na máquina e ajuste o apoio de pernas sobre os tornozelos.', 'Ajuste a trava sobre as coxas para firmar o corpo.', 'Flexione os joelhos, puxando o apoio para baixo e para trás.', 'Retorne à posição inicial de forma controlada.'], ARRAY[]::varchar[]),
('d8e9f0a1-b2c3-4567-8901-789012345678', 'Mesa flexora', '', ARRAY['Isquiotibiais'], ARRAY['Panturrilha', 'Glúteos'], 'Exercício deitado para isolar os músculos posteriores da coxa (isquiotibiais).', ARRAY['Deite-se de bruços na máquina, com os joelhos logo para fora da borda do banco.', 'Posicione o rolo de apoio na parte de trás dos tornozelos.', 'Flexione os joelhos, puxando os calcanhares em direção aos glúteos.', 'Retorne à posição inicial de forma controlada.'], ARRAY[]::varchar[]),
('e9f0a1b2-c3d4-5678-9012-890123456789', 'Panturrilha sentado', '', ARRAY['Sóleo'], ARRAY['Gastrocnêmio'], 'Exercício específico para o músculo sóleo (parte profunda da panturrilha), realizado sentado.', ARRAY['Sente-se na máquina e posicione a parte anterior dos pés na plataforma.', 'Coloque o apoio sobre os joelhos.', 'Eleve os calcanhares o máximo possível, contraindo a panturrilha.', 'Abaixe os calcanhares de forma controlada, alongando o músculo.'], ARRAY[]::varchar[]),
('f0a1b2c3-d4e5-6789-0123-901234567890', 'Cadeira Adutora', '', ARRAY['Adutores da coxa'], ARRAY[]::varchar[], 'Exercício de isolamento para a parte interna das coxas.', ARRAY['Sente-se na máquina com as costas apoiadas.', 'Posicione a parte interna dos joelhos contra os apoios.', 'Force as pernas para se fecharem, contraindo os músculos adutores.', 'Retorne à posição inicial de forma controlada.'], ARRAY[]::varchar[]),
('a1b2c3d4-e5f6-7890-1234-a23456789012', 'Cadeira Abdutora', '', ARRAY['Glúteo médio', 'Glúteo mínimo'], ARRAY[]::varchar[], 'Exercício de isolamento para a parte lateral dos glúteos e coxas.', ARRAY['Sente-se na máquina com as costas apoiadas.', 'Posicione a parte externa dos joelhos contra os apoios.', 'Force as pernas para se abrirem, contraindo os glúteos.', 'Retorne à posição inicial de forma controlada.'], ARRAY[]::varchar[]),
('b2c3d4e5-f6a7-8901-2345-b34567890123', 'Abdominal máquina', '', ARRAY['Reto abdominal'], ARRAY['Oblíquos'], 'Exercício para o abdômen realizado em máquina, que permite adicionar carga de forma segura.', ARRAY['Sente-se na máquina e ajuste o apoio do peito ou das costas.', 'Segure as manoplas ou posicione os braços no apoio.', 'Flexione o tronco para frente, contraindo o abdômen.', 'Retorne à posição inicial de forma controlada.'], ARRAY[]::varchar[]),
('c3d4e5f6-a7b8-9012-3456-c45678901234', 'Prancha', '', ARRAY['Core (Reto abdominal, Transverso)'], ARRAY['Lombar', 'Glúteos', 'Ombros'], 'Exercício isométrico fundamental para o fortalecimento do core e estabilização da coluna.', ARRAY['Apoie os antebraços e as pontas dos pés no chão.', 'Mantenha o corpo reto como uma prancha, da cabeça aos calcanhares.', 'Contraia o abdômen e os glúteos para evitar que o quadril caia.', 'Sustente a posição pelo tempo determinado.'], ARRAY[]::varchar[]);
